import Foundation

/// Domain-neutral hypothesis contract used by every investigation after R04.
/// These are PredatorLab-authored diagnostic reasoning paths until their individual claims are source-verified.
struct AuthoredDiagnosticHypothesis: Identifiable, Codable, Equatable {
    let id: String
    var title: String
    var mechanism: String
    var supportingEvidence: [String]
    var contradictingEvidence: [String]
    var requiredEvidence: [String]
    var nextMeasurements: [String]
    var evidenceBoundary: String
}

