        .init(id:"TH2", title:"Cooling-system recovery limitation", mechanism:"Thermal state recovers more slowly than comparable historical runs.", supportingEvidence:["Recovery time is a cohort outlier"], contradictingEvidence:["Recovery distribution matches baseline"], requiredEvidence:["Repeated thermal cycles", "coolant/IAT2", "speed/load"], nextMeasurements:["Measure normalized recovery time across comparable sessions"], evidenceBoundary:"Slow recovery needs physical cooling-system evidence before component replacement."),
